static enum gkyl_gk_trapped_passing_orbit_type
trapped_passing_orbit_from_species_bc(enum gkyl_gyrokinetic_bc_type bc)
{
  switch (bc) {
    case GKYL_BC_GK_SPECIES_SHEATH:
      return GKYL_GK_TRAP_PASS_ORBIT_TRAPPED_SHEATH;
    case GKYL_BC_GK_SPECIES_REFLECT:
    case GKYL_BC_GK_SPECIES_ZERO_FLUX:
    case GKYL_BC_GK_SPECIES_PERIODIC:
    case GKYL_BC_GK_SPECIES_TWISTSHIFT:
      return GKYL_GK_TRAP_PASS_ORBIT_TRAPPED_WALL;
    default:
      return GKYL_GK_TRAP_PASS_ORBIT_PASSING;
  }
}

static void
gk_species_fdot_multiplier_write_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  double tm, int frame
)
{
}

static void
gk_species_fdot_multiplier_write_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  double tm, int frame
)
{
  struct timespec wst = gkyl_wall_clock();
  // DG metadata for multiplier.
  struct gkyl_msgpack_map_elem mpe_mult[] = {
    {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 0},
    {.key = "basis_type", .elem_type = GKYL_MP_STRING, .cval = "serendipity"},
{
  gkyl_array_scale_by_cell(combined_multiplier, fdmul->buffer);
}

// Advance: apply constant scale to combined_multiplier.
static void
gk_species_fdot_multiplier_advance_const(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_array_scale(combined_multiplier, fdmul->time_dilation_scale_const);
}

static void
gk_species_fdot_multiplier_advance_loss_cone_mult(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_comm_array_allgather(app->comm, &app->local, &app->global, phi, fdmul->phi_global);
  int zdim = app->cdim - 1;
  if (gks->lower_bc[zdim].type == GKYL_BC_GK_SPECIES_SHEATH) {
    gkyl_comm_array_allgather(
      app->comm, &app->local, &app->global, gks->phi_wall_lo.phi, fdmul->phi_wall_lo_global
    );
  }
  if (gks->upper_bc[zdim].type == GKYL_BC_GK_SPECIES_SHEATH) {
    gkyl_comm_array_allgather(
      app->comm, &app->local, &app->global, gks->phi_wall_up.phi, fdmul->phi_wall_up_global
    );
  }
  gkyl_loss_cone_mask_gyrokinetic_advance(
    fdmul->lcm_proj_op, &gks->local, &app->global, fdmul->bmag_global, fdmul->phi_global,
    fdmul->phi_wall_lo_global, fdmul->phi_wall_up_global, fdmul->buffer
  );
  gkyl_array_scale(fdmul->buffer, fdmul->time_dilation_scale_const);
  gkyl_array_scale_by_cell(combined_multiplier, fdmul->buffer);
}
#include <acutest.h>

#include <math.h>

#include <gkyl_gyrokinetic_priv.h>

struct wall_profile_ctx {
  double offset;
  double time_slope;
  double space_slope;
};

static void
wall_profile(double t, const double *xn, double *fout, void *ctx)
{
  const struct wall_profile_ctx *profile = ctx;
  fout[0] = profile->offset + profile->time_slope * t + profile->space_slope * xn[0];
}

static gkyl_gyrokinetic_app
make_app(void)
{
  gkyl_gyrokinetic_app app = {.cdim = 1, .use_gpu = false};
  double lower[] = {-1.0}, upper[] = {1.0};
  int cells[] = {4}, ghost[] = {1};

  gkyl_rect_grid_init(&app.grid, app.cdim, lower, upper, cells);
  gkyl_cart_modal_serendip(&app.basis, app.cdim, 1);
  gkyl_create_grid_ranges(&app.grid, ghost, &app.local_ext, &app.local);

  return app;
}

static void
check_profile(
  const gkyl_gyrokinetic_app *app, const struct gkyl_array *phi,
  const struct wall_profile_ctx *profile, double tm
)
{
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &app->local_ext);
  while (gkyl_range_iter_next(&iter)) {
    long lidx = gkyl_range_idx(&app->local_ext, iter.idx);
    const double *phi_c = gkyl_array_cfetch(phi, lidx);
    double xc[GKYL_MAX_DIM];
    gkyl_rect_grid_cell_center(&app->grid, iter.idx, xc);

    const double eta[] = {-1.0, 0.0, 1.0};
    for (int i = 0; i < 3; ++i) {
      double x = xc[0] + 0.5 * app->grid.dx[0] * eta[i];
      double expected = profile->offset + profile->time_slope * tm + profile->space_slope * x;
      TEST_CHECK(fabs(app->basis.eval_expand(&eta[i], phi_c) - expected) < 1e-12);
    }
  }
}

static void
test_species_wall_profiles(void)
{
  // A linear profile lies exactly in the P1 basis. Compare its DG expansion
  // at both cell endpoints and the center with the closed-form profile, first
